static void lamp(uint32_t*ot,char**pk,int x,int z,int tick){int p=3+((tick/8)&3);box(ot,pk,x-5,67,z,10,118,12,53,57,63);box(ot,pk,x-20,61,z-3,40,8,18,72,68,57);tri3(ot,pk,2,(V3){x-13,58,z-8},(V3){x,35,z},(V3){x+13,58,z-8},220,176+p*5,83);box(ot,pk,x-9,51,z-7,18,11,14,245,204,104);}
