    tree(ot,pk,-740,1270);tree(ot,pk,170,1310);tree(ot,pk,770,1260);lamp(ot,pk,-350,1120,tick);lamp(ot,pk,320,1120,tick+8);lamp(ot,pk,900,1120,tick+16);fence(ot,pk,-1120,1420,370);fence(ot,pk,690,1420,420);
