    villager(ot,pk,wx(278),wz(174),tick,(motes>0&&motes<3));if(motes<1)mote(ot,pk,wx(185),92,wz(176),tick);if(motes<2)mote(ot,pk,wx(348),82,wz(153),tick+12);if(motes<3)mote(ot,pk,wx(452),76,wz(141),tick+24);enemy(ot,pk,wx(503),wz(176),enemy_hp,tick);
